    const idx = rest.slice(2).search(/[/?#]/)
    if (idx === -1) {
      authority = rest.slice(2)
      rest = ''
    } else {
      authority = rest.slice(2, 2 + idx)
      rest = rest.slice(2 + idx)
    }
  }

  const hIdx = rest.indexOf('#')
  let beforeFragment, fragment
  if (hIdx === -1) {
    beforeFragment = rest
  } else {
    beforeFragment = rest.slice(0, hIdx)
    fragment = rest.slice(hIdx + 1)
  }

  const qIdx = beforeFragment.indexOf('?')
  let path, query
  if (qIdx === -1) {
    path = beforeFragment
  } else {
    path = beforeFragment.slice(0, qIdx)
    query = beforeFragment.slice(qIdx + 1)
  }

  return { scheme, authority, path, query, fragment }
